net.coobird.thumbnailator.resizers.ResizerFactory factory = net.coobird.thumbnailator.resizers.DefaultResizerFactory.getInstance();

int w = Math.max(4, sourceImage.getWidth());
int h = Math.max(4, sourceImage.getHeight());

java.awt.Dimension origSize = new java.awt.Dimension(w, h);
java.awt.Dimension downSize = new java.awt.Dimension(w / 4, h / 4);
java.awt.Dimension upSize = new java.awt.Dimension(w * 2, h * 2);

net.coobird.thumbnailator.resizers.Resizer downResizer = factory.getResizer(origSize, downSize);
net.coobird.thumbnailator.resizers.Resizer upResizer = factory.getResizer(origSize, upSize);
net.coobird.thumbnailator.resizers.Resizer defaultResizer = factory.getResizer();

assert downResizer != null && upResizer != null && defaultResizer != null : "Resizers must not be null";
assert !downResizer.getClass().equals(upResizer.getClass()) : "Factory should select different resizer implementations for upscaling vs downscaling";

System.out.println("__CHECK__ getResizer down=" + downResizer.getClass().getSimpleName() + ", up=" + upResizer.getClass().getSimpleName());
